def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    o = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and o[j] > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                nearest[i] = min(nearest[i], d / (r[i] + r[j]))
    weight = sum(o[i] for i in range(n) if isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    mean = sum(o[i] * nearest[i] for i in range(n) if isfinite(nearest[i])) / weight
    var = sum(o[i] * (nearest[i] - mean) ** 2 for i in range(n) if isfinite(nearest[i])) / weight
    return sqrt(max(var, 0.0)) / mean if mean > 0 else 0.0

