def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    o = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    counts = {}
    for i in range(n):
        if r[i] is not None and r[i] > 0:
            e = sites[i].get('element')
            counts[e] = counts.get(e, 0.0) + o[i]
    mass = sum(counts.values())
    if mass <= 0:
        return 0.0
    random_unlike = 1.0 - sum((x / mass) ** 2 for x in counts.values())
    unlike = 0.0
    weight = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                w = o[i] * o[j] * exp(-((d / (1.2 * (r[i] + r[j]))) ** 6))
                weight += w
                if sites[i].get('element') != sites[j].get('element'):
                    unlike += w
    return unlike / weight - random_unlike if weight > 1e-12 else 0.0

